'use strict';
(()=>{
 const $=s=>document.querySelector(s);
 const link=document.createElement('link');link.rel='stylesheet';link.href='ai-builder.css?v=20261127.5';document.head.append(link);
 const main=document.querySelector('main');
 const panel=document.createElement('section');panel.id='aiBuilder';panel.className='ai-builder';panel.setAttribute('aria-label','AI circuit builder');
 panel.innerHTML=`<div class="ai-heading"><div class="ai-title"><span class="ai-spark">✳</span><span><strong>MCC AI chat</strong><small id="aiState">Choose a sign-in method</small></span></div><div class="ai-actions"><a id="aiChatUsage" class="ai-usage" href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener" hidden>Manage usage</a><button type="button" id="aiDisconnect" class="ai-disconnect" hidden>Clear key</button><button type="button" id="aiChatDisconnect" class="ai-disconnect" hidden>Disconnect ChatGPT</button><button type="button" id="closeAI" class="dock-close" aria-label="Close AI chat">×</button></div></div><div class="ai-auth-options"><button type="button" id="apiKeyMode" class="ai-auth-choice active">OpenAI API key</button><button type="button" id="chatGPTMode" class="ai-auth-choice">ChatGPT plan</button><p id="chatGPTNotice" class="ai-auth-notice" hidden>ChatGPT plan sign-in works in local MCC. Hosted access requires OpenAI approval. <a href="https://openai.com/form/sign-in-with-chatgpt-interest/" target="_blank" rel="noopener">Request access</a></p></div><div id="aiMessages" class="ai-messages" aria-live="polite"><div class="ai-message assistant">Connect with an OpenAI API key, or use your ChatGPT plan when running MCC locally.</div></div><form id="aiForm" class="ai-form"><label class="sr-only" id="aiInputLabel" for="aiPrompt">OpenAI API key</label><input id="aiPrompt" type="password" autocomplete="off" spellcheck="false" maxlength="1200" placeholder="Paste your OpenAI API key" required><button id="aiSend" class="primary" type="submit" aria-label="Check API key">Connect</button></form><div class="ai-note">API keys stay in this tab. Local ChatGPT credentials stay in MCC’s protected device storage. Check part ratings before wiring hardware.</div>`;
 main.append(panel);
 const keyStatus=$('#aiState'),disconnect=$('#aiDisconnect'),chatDisconnect=$('#aiChatDisconnect'),chatUsage=$('#aiChatUsage'),form=$('#aiForm'),prompt=$('#aiPrompt'),send=$('#aiSend'),messages=$('#aiMessages'),inputLabel=$('#aiInputLabel'),apiMode=$('#apiKeyMode'),chatMode=$('#chatGPTMode'),chatNotice=$('#chatGPTNotice');
 $('#closeAI').onclick=()=>window.setChatOpen(false);
 let apiKey='',busy=false,history=[],provider='apiKey',chatSession=null,chatModels=[];
 function addMessage(role,text,sources=[]){const el=document.createElement('div');el.className=`ai-message ${role}`;el.textContent=text;messages.append(el);if(role==='assistant'&&sources.length){const refs=document.createElement('div');refs.className='ai-sources';const label=document.createElement('strong');label.textContent='Research sources';refs.append(label);for(const source of sources.slice(0,5)){if(!source||typeof source.url!=='string'||!/^https:\/\//.test(source.url))continue;const a=document.createElement('a');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=source.title||new URL(source.url).hostname;refs.append(a)}if(refs.childElementCount>1)messages.append(refs)}messages.scrollTop=messages.scrollHeight}
 function setApiKeyView(){provider='apiKey';apiMode.classList.add('active');chatMode.classList.remove('active');chatConnect.hidden=true;chatNotice.hidden=true;chatDisconnect.hidden=true;chatUsage.hidden=true;disconnect.hidden=!apiKey;prompt.disabled=false;prompt.type=apiKey?'text':'password';prompt.placeholder=apiKey?'Describe a circuit idea…':'Paste your OpenAI API key';inputLabel.textContent=apiKey?'Describe a circuit idea':'OpenAI API key';keyStatus.textContent=apiKey?'API key connected · MCC AI ready':'OpenAI API key · Connect to build';send.disabled=false;send.textContent=apiKey?'Build':'Connect';send.setAttribute('aria-label',apiKey?'Build this idea':'Check API key');panel.classList.toggle('ai-ready',!!apiKey)}
 function setChatGPTView(){provider='chatgpt';apiMode.classList.remove('active');chatMode.classList.add('active');disconnect.hidden=true;chatUsage.hidden=!chatSession?.sharing;chatNotice.hidden=localOnly;chatDisconnect.hidden=!chatSession?.sharing;prompt.disabled=!chatSession?.sharing;prompt.type='text';prompt.placeholder=chatSession?.sharing?'Describe a circuit idea…':'Choose ChatGPT plan to sign in';inputLabel.textContent='Describe a circuit idea';keyStatus.textContent=chatSession?.sharing?`Using ChatGPT plan · ${chatSession.profileLabel||'Connected'}`:localOnly?'Sign in with ChatGPT to build':'Hosted ChatGPT sign-in needs approval';send.disabled=!chatSession?.sharing;send.textContent=chatSession?.sharing?'Build':'Connect';send.setAttribute('aria-label',chatSession?.sharing?'Build this idea':'Connect ChatGPT');panel.classList.toggle('ai-ready',!!chatSession?.sharing)}
 function setConnected(){provider='apiKey';prompt.value='';setApiKeyView();addMessage('assistant','Your key works. Describe a circuit and I’ll add the supported parts and connections.')}
 apiMode.onclick=()=>setApiKeyView();
 disconnect.onclick=()=>{apiKey='';history=[];prompt.value='';setApiKeyView();addMessage('assistant','The API key was cleared from this tab. Paste a key to reconnect.')};
 const localOnly=['localhost','127.0.0.1'].includes(location.hostname);
 async function refreshChatGPT(){if(!localOnly)return;try{const response=await fetch('/api/chatgpt/session');const data=await response.json();chatSession=data.session;if(chatSession?.sharing){const models=await fetch('/api/chatgpt/models');const list=await models.json();chatModels=list.models||[];provider='chatgpt';setChatGPTView()}}catch{}}
 async function connectChatGPT(){if(!localOnly||busy)return;busy=true;chatMode.disabled=true;chatMode.textContent='Waiting for sign-in…';keyStatus.textContent='Complete sign-in in the browser that opens…';try{const response=await fetch('/api/chatgpt/sign-in',{method:'POST'});const data=await response.json();if(!response.ok)throw Error(data.error||'ChatGPT sign-in did not complete.');chatSession=data.session;const modelResponse=await fetch('/api/chatgpt/models');const modelData=await modelResponse.json();if(!modelResponse.ok)throw Error(modelData.error||'Could not load ChatGPT models.');chatModels=modelData.models||[];history=[];prompt.value='';setChatGPTView();addMessage('assistant',`Connected to ${chatSession.profileLabel||'ChatGPT'}. Using your ChatGPT plan with MCC.`)}catch(error){keyStatus.textContent='ChatGPT sign-in failed';addMessage('assistant',error.message)}finally{busy=false;chatMode.disabled=false;chatMode.textContent='ChatGPT plan'}};
 chatMode.onclick=()=>{setChatGPTView();if(localOnly&&!chatSession?.sharing)void connectChatGPT()};
 chatDisconnect.onclick=async()=>{chatDisconnect.disabled=true;try{const response=await fetch('/api/chatgpt/disconnect',{method:'POST'}),data=await response.json();if(!response.ok)throw Error(data.error||'Could not disconnect ChatGPT.');chatSession=data.session;chatModels=[];history=[];prompt.value='';setApiKeyView();addMessage('assistant','ChatGPT was disconnected from MCC.')}catch(error){addMessage('assistant',error.message)}finally{chatDisconnect.disabled=false}};
 setApiKeyView();void refreshChatGPT();
 function currentState(){return {components:window.CanvasAI.current()}}
 async function ask(idea){
  const endpoint=window.CANVAS_AI_ENDPOINT||'/api/build';
  const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'build',provider,apiKey,idea,context:currentState(),history:history.slice(-8)})});
  let data;try{data=await response.json()}catch{throw Error(response.status===404?'No AI server is deployed at this site. Deploy the project server or configure its HTTPS URL in dist/ai-config.js.':'The project server returned an unreadable response.')}
  if(!response.ok)throw Error(data?.error||`The project server could not complete this request (${response.status}).`);
  if(!data?.plan)throw Error('The project server did not return a build plan. Try describing the circuit more simply.');
  if(Array.isArray(data.definitions)&&data.definitions.length){
   const definitions=new Map(ComponentRegistry.all().map(def=>[def.id,def]));
   for(const def of data.definitions)definitions.set(def.id,def);
   window.refreshComponentRegistry([...definitions.values()]);
  }
  const applied=window.CanvasAI.apply(data.plan);return {summary:data.plan.summary, ...applied,sources:Array.isArray(data.sources)?data.sources:[]};
 }
 async function checkKey(candidate){const endpoint=window.CANVAS_AI_ENDPOINT||'/api/build';const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'check',apiKey:candidate})});let data;try{data=await response.json()}catch{throw Error(response.status===404?'No AI server is deployed at this site. Configure its HTTPS URL in dist/ai-config.js.':'The project server returned an unreadable response.')};if(!response.ok||!data?.valid)throw Error(data?.error||`The project server could not check this key (${response.status}).`)}
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;const value=prompt.value.trim();if(!value)return;
  if(provider==='chatgpt'&&!chatSession?.sharing)return;
  if(provider==='apiKey'&&!apiKey){busy=true;send.disabled=true;send.textContent='Checking…';keyStatus.textContent='Checking whether the key works…';try{await checkKey(value);apiKey=value;setConnected()}catch(err){keyStatus.textContent='Could not verify key';addMessage('assistant',`I couldn’t connect that key: ${err.message}`)}finally{busy=false;send.disabled=false;if(!apiKey)send.textContent='Connect';prompt.focus()}return}
  const idea=value;
  prompt.value='';addMessage('user',idea);busy=true;send.disabled=true;send.textContent='Building…';keyStatus.textContent='Thinking and checking connections…';
  try{const result=await ask(idea);const parts=result.added?`${result.added} part${result.added===1?'':'s'}`:'existing parts';const wires=result.connected?` and ${result.connected} connection${result.connected===1?'':'s'}`:'';const note=`${result.summary||'Build added.'} Added ${parts}${wires}. Press Run simulation when you’re ready.`;addMessage('assistant',note,result.sources);history.push({role:'user',content:idea},{role:'assistant',content:note});history=history.slice(-12);keyStatus.textContent='AI ready · Project server'}catch(err){addMessage('assistant',`I couldn’t build that yet: ${err.message}`);keyStatus.textContent='AI ready · Project server'}finally{busy=false;send.disabled=false;send.innerHTML='Build <span>↗</span>';prompt.focus()}
 };
 prompt.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();form.requestSubmit()}});
})();
